def transform(g):
    h=len(g);w=len(g[0])
    from collections import Counter
    cnt=Counter(x for r in g for x in r if x)
    (A,_),(B,_)=cnt.most_common(2)
    def bbox(c):
        rs=[i for i in range(h) for j in range(w) if g[i][j]==c]
        cs=[j for i in range(h) for j in range(w) if g[i][j]==c]
        return min(rs),max(rs),min(cs),max(cs)
    ar0,ar1,ac0,ac1=bbox(A); br0,br1,bc0,bc1=bbox(B)
    t=min(br1-br0+1,bc1-bc0+1)//2+1
    o=[row[:] for row in g]
    for i in range(ar0-t,ar1+t+1):
        for j in range(ac0-t,ac1+t+1):
            if 0<=i<h and 0<=j<w and o[i][j]==0: o[i][j]=B
    return o
